    try: outage_refund(mk(),Decimal(a),T0)
    except BillingError as e: print("amt",a,e.code)
# wrong state
try: outage_refund(mk(status="authorized"),Decimal("1"),T0)
except BillingError as e: print("state",e.code)
# already refunded
try: outage_refund(mk(status="refunded",ref="80.00"),Decimal("1"),T0)
except BillingError as e: print("state2",e.code)
# float rejected
try: outage_refund(mk(),1.5,T0)
except BillingError as e: print("float",e.code)
